// Independent browser/output acceptance for the existing Flatten PDF tool.
const assert=require('node:assert/strict');const fs=require('node:fs/promises');const path=require('node:path');
const {chromium}=require(process.env.PDFPILOT_PLAYWRIGHT_MODULE||'playwright');
const {PDFDocument,PDFName}=require('pdf-lib');const sharp=require('sharp');
const {inspectPDF}=require('./qa-output-inspector-20261004.cjs');
const base=process.argv[2]||'http://127.0.0.1:4400';const out=path.resolve(process.argv[3]||'docs/product-completion/qa-flatten-independent-2026-10-04');
const fixtures=process.env.PDFPILOT_FLATTEN_FIXTURES||'/tmp/pdfpilot-flatten-b';
const report={base,started:new Date().toISOString(),cases:[],errors:[],screenshots:[],environment:'Isolated headless desktop Chromium; emulated viewports'};
async function ready(page){await page.getByRole('button',{name:/Switch to (dark|light) mode/}).waitFor({timeout:120000});}
async function shot(page,state){for(const width of [375,768,1440]){await page.setViewportSize({width,height:1000});const name=`${state}-${width}.png`;await page.screenshot({path:path.join(out,name),fullPage:true});const size=await page.evaluate(()=>({width:innerWidth,scrollWidth:document.documentElement.scrollWidth}));report.screenshots.push({name,...size});assert.ok(size.scrollWidth<=width+1,`${state} overflows ${width}px`);}}
async function inspectFlatten(source,download){const src=await PDFDocument.load(await fs.readFile(source));const dst=await PDFDocument.load(await fs.readFile(download));assert.equal(dst.getPageCount(),src.getPageCount());assert.equal(dst.getForm().getFields().length,0);let annotationTypes=[];for(let i=0;i<src.getPageCount();i++){assert.deepEqual(dst.getPage(i).getCropBox(),src.getPage(i).getCropBox());assert.equal(dst.getPage(i).getRotation().angle,src.getPage(i).getRotation().angle);const annots=dst.getPage(i).node.Annots();if(annots)for(const a of annots.asArray()){const kind=dst.context.lookup(a).get(PDFName.of('Subtype'))?.toString();assert.notEqual(kind,'/Widget');annotationTypes.push(kind);}}
 const sourceInfo=await inspectPDF(source,out);const outputInfo=await inspectPDF(download,out);const comparisons=[];for(let i=0;i<src.getPageCount();i++){const a=await sharp(path.join(out,sourceInfo.renders[i])).raw().toBuffer();const b=await sharp(path.join(out,outputInfo.renders[i])).raw().toBuffer();assert.equal(a.length,b.length);let changed=0,max=0;for(let j=0;j<a.length;j++){const delta=Math.abs(a[j]-b[j]);if(delta)changed++;max=Math.max(delta,max);}comparisons.push({page:i+1,changedChannels:changed,maxChannelDifference:max,totalChannels:a.length});assert.equal(changed,0,'Flattened visible appearance should match source exactly');}
 return {fields:0,annotationTypes,source:sourceInfo,output:outputInfo,comparisons};}
async function main(){await fs.mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true,executablePath:process.env.PDFPILOT_CHROME||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});const context=await browser.newContext({viewport:{width:1440,height:1000},acceptDownloads:true});const page=await context.newPage();page.on('pageerror',e=>report.errors.push(e.message));
try{const response=await page.goto(base+'/flatten-pdf',{waitUntil:'domcontentloaded',timeout:120000});report.response={status:response.status(),headers:await response.allHeaders()};assert.equal(response.status(),200);await ready(page);await shot(page,'initial');
 if (!process.env.PDFPILOT_QA_ERRORS_ONLY) {
 await page.locator('input[type=file]').first().setInputFiles(path.join(fixtures,'forms-source.pdf'));await page.getByRole('button',{name:'Flatten PDF',exact:true}).waitFor();await shot(page,'loaded');await page.getByRole('button',{name:'Flatten PDF',exact:true}).click();await page.getByText('6 fields flattened · 2 pages',{exact:true}).waitFor({timeout:90000});const pending=page.waitForEvent('download');await page.getByRole('button',{name:'Download PDF',exact:true}).first().click();const dl=await pending;const dest=path.join(out,dl.suggestedFilename());await dl.saveAs(dest);const checked=await inspectFlatten(path.join(fixtures,'forms-source.pdf'),dest);assert.ok(checked.annotationTypes.includes('/Link'));assert.ok(checked.annotationTypes.includes('/Text'));assert.match(checked.output.text.join(' '),/Ada Lovelace/);report.cases.push({name:'form-values-and-original-content',status:'passed',download:path.basename(dest),...checked});await shot(page,'result');await page.getByRole('button',{name:'Switch to dark mode',exact:true}).click();await shot(page,'result-dark');await page.getByRole('button',{name:'Start over',exact:true}).click();await page.locator('input[type=file]').first().waitFor({state:'attached'});report.cases.push({name:'reset',status:'passed'});
 for(const name of ['matrix-source.pdf','unicode-source.pdf','invisible-bit-source.pdf']){await page.locator('input[type=file]').first().setInputFiles(path.join(fixtures,name));await page.getByRole('button',{name:'Flatten PDF',exact:true}).click();await page.getByRole('button',{name:'Download PDF',exact:true}).first().waitFor({timeout:90000});const p=page.waitForEvent('download');await page.getByRole('button',{name:'Download PDF',exact:true}).first().click();const d=await p;const output=path.join(out,d.suggestedFilename());await d.saveAs(output);report.cases.push({name,status:'passed',...await inspectFlatten(path.join(fixtures,name),output)});await page.getByRole('button',{name:'Start over',exact:true}).click();}
 }
 const invalid={name:'invalid.pdf',mimeType:'application/pdf',buffer:Buffer.from('this is not a PDF')};await page.locator('input[type=file]').first().setInputFiles(invalid);await page.getByRole('button',{name:'Flatten PDF',exact:true}).click();await page.locator('article [role=alert]').first().waitFor();report.invalidMessage=await page.locator('article [role=alert]').first().innerText();assert.match(report.invalidMessage,/PDF|read|valid/i);await shot(page,'error');await page.getByRole('button',{name:'Retry unfinished PDFs',exact:true}).click();await page.getByRole('button',{name:'Retry unfinished PDFs',exact:true}).waitFor();await page.getByRole('button',{name:'Remove invalid.pdf',exact:true}).click();await page.locator('input[type=file]').first().setInputFiles(path.join(fixtures,'forms-source.pdf'));await page.getByRole('button',{name:'Flatten PDF',exact:true}).click();await page.getByText('6 fields flattened · 2 pages',{exact:true}).waitFor();report.cases.push({name:'malformed-retry-remove-replace',status:'passed'});
 report.status='passed';
}catch(e){report.status='failed';report.failure=e.message;report.failureText=await page.locator('body').innerText().catch(()=> '');await page.screenshot({path:path.join(out,'failure.png'),fullPage:true}).catch(()=>{});console.error(e);process.exitCode=1;}finally{report.finished=new Date().toISOString();await fs.writeFile(path.join(out,'report.json'),JSON.stringify(report,null,2));await browser.close();console.log(JSON.stringify({status:report.status,cases:report.cases.map(x=>x.name),failure:report.failure}));}}
main().catch(e=>{console.error(e);process.exitCode=1;});
